const listAssignedRequisitesForTrader = `-- name: ListAssignedRequisitesForTrader :many
WITH current_shift AS (
    SELECT trader_shifts.id
    FROM trader_shifts
    WHERE trader_shifts.team_id = $1
      AND trader_shifts.trader_id = $2
      AND trader_shifts.status IN ('open', 'closing')
    ORDER BY trader_shifts.started_at DESC, trader_shifts.id DESC
    LIMIT 1
)
SELECT
    r.id,
    r.team_id,
    r.phone,
    r.method_type,
    r.bank_code,
    ''::text AS bank_name,
    r.proxy,
    r.employee_comment,
    r.status,
    ra.id AS assignment_id,
    ra.status AS assignment_status,
    ra.assigned_for_date,
    ra.target_turnover_minor,
    COALESCE(sr.id, 0) AS shift_requisite_id,
    COALESCE(sr.card_number, r.card_number, '') AS card_number,
    COALESCE(sr.holder_name, r.holder_name, '') AS holder_name,
    COALESCE(sr.status, '') AS shift_requisite_status,
    sr.taken_at,
    sr.released_at,
    COALESCE(sr.inbound_turnover_minor, 0) AS inbound_turnover_minor,
    COALESCE(sr.outbound_turnover_minor, 0) AS outbound_turnover_minor,
    COALESCE(sr.closing_balance_minor, 0) AS closing_balance_minor
FROM requisite_assignments ra
JOIN requisites r ON r.id = ra.requisite_id
LEFT JOIN current_shift cs ON true
LEFT JOIN LATERAL (
    SELECT sr.id, sr.team_id, sr.shift_id, sr.trader_id, sr.requisite_id, sr.assignment_id, sr.card_number, sr.holder_name, sr.taken_at, sr.released_at, sr.status, sr.created_at, sr.updated_at, sr.inbound_turnover_minor, sr.outbound_turnover_minor, sr.closing_balance_minor, sr.tl_reconciliation_status, sr.last_teamlead_reconciliation_id, sr.tl_reconciled_at
    FROM shift_requisites sr
    WHERE sr.shift_id = cs.id
      AND sr.requisite_id = r.id
    ORDER BY sr.taken_at DESC, sr.id DESC
    LIMIT 1
) sr ON true
WHERE ra.team_id = $1
  AND ra.trader_id = $2
  AND ra.unassigned_at IS NULL
  AND ra.status IN ('planned', 'assigned', 'in_work')
  AND ra.assigned_for_date <= $3::date
  AND r.deleted_at IS NULL
  AND r.status = 'active'
  AND (
      $4::bigint IS NULL
      OR COALESCE(sr.id, 0) <> $4::bigint
  )
  AND (
      COALESCE(cardinality($5::text[]), 0) = 0
      OR (
          ('assigned' = ANY($5::text[]) AND sr.id IS NULL)
          OR ('in_work' = ANY($5::text[]) AND sr.status = 'active')
          OR ('correction' = ANY($5::text[]) AND sr.status = 'correction')
          OR ('blocked' = ANY($5::text[]) AND sr.status = 'blocked')
          OR (sr.status = ANY($5::text[]))
      )
  )
  AND (
      $6::text = ''
      OR lower(r.phone) LIKE '%' || lower($6::text) || '%'
      OR (
          COALESCE(cardinality($7::text[]), 0) > 0
          AND r.bank_code = ANY($7::text[])
      )
      OR lower(COALESCE(sr.card_number, r.card_number, '')) LIKE '%' || lower($6::text) || '%'
      OR (
          $8::text <> ''
          AND (
              regexp_replace(r.phone, '[^0-9]', '', 'g') LIKE '%' || $8::text || '%'
              OR regexp_replace(COALESCE(sr.card_number, r.card_number, ''), '[^0-9]', '', 'g') LIKE '%' || $8::text || '%'
          )
      )
  )
ORDER BY ra.assigned_for_date DESC, r.created_at DESC, r.id DESC
LIMIT $10
OFFSET $9
`

